const button=document.querySelector('.menu');const nav=document.querySelector('#nav');if(button&&nav){button.addEventListener('click',()=>{const open=nav.classList.toggle('open');button.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');button.setAttribute('aria-expanded','false');nav.querySelectorAll('.nav-group.open').forEach(g=>g.classList.remove('open'))}));nav.querySelectorAll('.drop-toggle').forEach(toggle=>toggle.addEventListener('click',e=>{e.stopPropagation();const group=toggle.closest('.nav-group');const open=!group.classList.contains('open');nav.querySelectorAll('.nav-group.open').forEach(g=>{g.classList.remove('open');g.querySelector('.drop-toggle').setAttribute('aria-expanded','false')});group.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open))}));document.addEventListener('click',e=>{if(!nav.contains(e.target)){nav.querySelectorAll('.nav-group.open').forEach(g=>{g.classList.remove('open');g.querySelector('.drop-toggle').setAttribute('aria-expanded','false')})}})}
